import os, re
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')

# Parse all demo pairs and test input
pairs = {}
G = {}
in_demo = False
demo_num = 0
current_grid = []
dims = (0, 0)

for line in t.split('\n'):
    if 'Demo pair' in line or 'Test input' in line:
        # Save previous grid if any
        if current_grid and dims[0] > 0:
            pairs[(demo_num, 'output')] = current_grid

        if 'Test input' in line:
            h, w = map(int, line.split()[1:3])
            current_grid = [[int(x) for x in line.split()[3:]]]
        elif 'Demo pair' in line:
            parts = line.split()
            h, w = int(parts[1]), int(parts[2])
            demo_num += 1
        else:
            # Data row
            if len(current_grid) == dims[0]:
                continue
            G[h] = current_grid
            current_grid = [[int(x) for x in line.split()]]

print(f"Pairs: {pairs}")
print(f"G keys: {G.keys()}")
if (1, 'output') in pairs:
    print(f"Demo 1 output: {pairs[(1,'output')]}")

